SELECT SUM(CANCELLED_ORDER_COUNT) AS TOTAL_CANCELLED, SUM(ORDER_COUNT) AS TOTAL_ORDERS, SUM(CANCELLED_ORDER_COUNT) / SUM(ORDER_COUNT) AS OVERALL_CANCELLATION_RATE
FROM ZOMATO_DLR.MARTS.MART_ORDER_CITY_CURRENCY_DAY_UTC
WHERE ORDER_DATE_UTC >= '2025-01-01' AND ORDER_DATE_UTC < '2026-01-01';
